import fs from 'node:fs';
import zlib from 'node:zlib';
import crypto from 'node:crypto';
const encoded = '';
const html=zlib.gunzipSync(Buffer.from(encoded,'base64'));
if(crypto.createHash('sha256').update(html).digest('hex')!=='941e693bdd04f22f64df807b929633564fb9022c48201332f74acdcd8d91f325')throw new Error('Viewer checksum mismatch');
fs.mkdirSync('dist',{recursive:true});
fs.writeFileSync('dist/index.html',html);
console.log('Static viewer ready: '+html.length+' bytes');
